// Package golden is the domain-scoped home for the Golden registry
// (OT-P0-001). A Golden is a scenario that was generated by
// `vrooli scenario generate <template>` and has not been hand-modified
// since — i.e. template-pristine. Every skill validation run uses a
// Golden as its substrate.
//
// Layering mirrors the canonical Vrooli pattern (api-steer / storage-steer):
//
//	HTTP → handler → Service (validates) → Repository (persists)
//	                     ↑                      ↑
//	                     FakeService            FakeRepository
//
// types.go owns the domain entity and the typed sentinels handlers
// translate at the transport edge. repository.go owns the persistence
// seam. service.go owns the application surface. The proto wire types
// live in packages/proto/ and never import this package.
package golden

import (
	"fmt"
	"time"
)

// Golden is the internal domain shape for a registered template-pristine
// scenario. Distinct from the proto wire type at
// packages/proto/gen/go/.../v1/golden.Golden — handlers translate at the
// boundary so the domain layer never imports proto.
type Golden struct {
	ID                    string
	Slug                  string
	TemplateID            string
	TemplateVersionPinned string
	Path                  string
	CreatedAt             time.Time
	LastRegeneratedAt     time.Time
}

// RegisterInput is the explicit input DTO Service.Register accepts.
// Distinct from Golden so callers cannot accidentally pass ID or
// timestamps the service has no way to honour.
type RegisterInput struct {
	Slug            string
	TemplateID      string
	TemplateVersion string
	Path            string
}

// UpdateInput is the explicit input DTO Service.Update accepts. Empty
// string fields mean "leave unchanged" — letting handlers pass partial
// patches without a separate field-mask plumbing.
type UpdateInput struct {
	Slug            string // required: lookup key
	Path            string // empty => unchanged
	TemplateVersion string // empty => unchanged
}

// ErrGoldenNotFound is the typed sentinel returned when no row matches.
// Handlers translate via errors.As into Connect's CodeNotFound.
type ErrGoldenNotFound struct {
	Slug string
}

func (e ErrGoldenNotFound) Error() string {
	return fmt.Sprintf("golden %q not found", e.Slug)
}

// ErrInvalidGolden is the typed sentinel returned by the service when
// input validation fails. Field names the offending field; Reason is a
// human-safe explanation. Handlers translate via errors.As into
// Connect's CodeInvalidArgument.
type ErrInvalidGolden struct {
	Field  string
	Reason string
}

func (e ErrInvalidGolden) Error() string {
	return fmt.Sprintf("%s: %s", e.Field, e.Reason)
}

// ErrGoldenAlreadyExists is the typed sentinel returned when Register
// would create a row with a slug that already exists. Handlers translate
// via errors.As into Connect's CodeAlreadyExists.
type ErrGoldenAlreadyExists struct {
	Slug string
}

func (e ErrGoldenAlreadyExists) Error() string {
	return fmt.Sprintf("golden %q already exists", e.Slug)
}

// ErrRegenerateFailed wraps subprocess / IO failures from the
// regenerator runner so the service layer can surface a structured
// error without leaking stdout/stderr to clients. Handlers translate
// via errors.As into Connect's CodeInternal.
type ErrRegenerateFailed struct {
	Slug    string
	Wrapped error
}

func (e ErrRegenerateFailed) Error() string {
	return fmt.Sprintf("regenerate golden %q: %v", e.Slug, e.Wrapped)
}

func (e ErrRegenerateFailed) Unwrap() error { return e.Wrapped }
